  assign row_a[55] = s7_c55_fa0_s;
  assign row_b[55] = c7_c54_fa0;
  assign row_a[56] = s7_c56_fa0_s;
  assign row_b[56] = c7_c55_fa0;
  assign row_a[57] = s7_c57_fa0_s;
  assign row_b[57] = c7_c56_fa0;
  assign row_a[58] = s7_c58_fa0_s;
  assign row_b[58] = c7_c57_fa0;
  assign row_a[59] = s7_c59_fa0_s;
  assign row_b[59] = c7_c58_fa0;
  assign row_a[60] = s7_c60_fa0_s;
  assign row_b[60] = c7_c59_fa0;
  assign row_a[61] = s7_c61_fa0_s;
  assign row_b[61] = c7_c60_fa0;
  assign row_a[62] = pp_31_31;
  assign row_b[62] = c7_c61_fa0;
  assign row_a[63] = 1'b0;
  assign row_b[63] = 1'b0;

  ksa #(
    .WIDTH(2*WIDTH)
  ) ksa1 (
    .a(row_a),
    .b(row_b),
    .c_in(1'b0),
    .sum(final_sum),
    .c_out(final_cout)
   );

  assign product = final_sum;

endmodule

module ha (
    input logic a,
    input logic b,
    output logic sum,
    output logic c_out
);
  assign sum = a ^ b;
  assign c_out = a & b;
endmodule

module fa (
    input logic a,
    input logic b,
    input logic c_in,
    output logic sum,
    output logic c_out
);
  assign sum = a ^ b ^ c_in;
  assign c_out = (a & b) | ((a ^ b) & c_in);
endmodule

